//! Print docs/CONTENT.md: which cards are implemented (scripted or keyword-only).
//! Usage: cargo run --release -p taverngym --example content_report > docs/CONTENT.md

use taverngym::cards::{CardKind, db};
use taverngym::script::{implemented, script};

fn main() {
    let d = db();
    println!("# Implemented content\n");
    println!(
        "Generated by `cargo run --release -p taverngym --example content_report > docs/CONTENT.md`."
    );
    println!(
        "\"Scripted\" = behaviour implemented in `crates/taverngym/src/content`; \"keyword-only\" = the"
    );
    println!(
        "card's full text is keywords the engine handles generically. Golden forms reuse the normal"
    );
    println!("script with the golden numbers from the bundle text.\n");

    // Shop pool = current candidates without a non-standard IS_BACON_POOL_MINION tag (RulesConfig::strict_pool_tag).
    let pool: Vec<_> = d
        .iter()
        .filter(|c| c.pools.minion && c.pool_tag <= 1)
        .collect();
    let scripted = pool.iter().filter(|c| script(c.cid).is_some()).count();
    let impl_total = pool.iter().filter(|c| implemented(c.cid)).count();
    let heroes: Vec<_> = d
        .iter()
        .filter(|c| c.pools.hero && c.kind == CardKind::Hero)
        .collect();
    let heroes_ok = heroes
        .iter()
        .filter(|h| h.hero_power.is_some_and(|hp| script(hp).is_some()))
        .count();
    let spells: Vec<_> = d
        .iter()
        .filter(|c| c.pools.spell && c.kind == CardKind::TavernSpell)
        .collect();
    let spells_ok = spells.iter().filter(|c| script(c.cid).is_some()).count();
    let trinkets: Vec<_> = d.iter().filter(|c| c.pools.trinket).collect();
    let trinkets_ok = trinkets.iter().filter(|c| script(c.cid).is_some()).count();
    let gifts: Vec<_> = d
        .iter()
        .filter(|c| c.kind == CardKind::DarkGift && c.window.is_some())
        .collect();
    let gifts_ok = gifts.iter().filter(|c| script(c.cid).is_some()).count();
    let timewarp: Vec<_> = d.iter().filter(|c| c.pools.timewarp).collect();
    let tier7: Vec<_> = d.iter().filter(|c| c.pools.tier7).collect();

    println!("| Category | Implemented | Current candidates |");
    println!("| --- | ---: | ---: |");
    println!(
        "| Shop minions (tiers 1-6, incl. keyword-only) | {impl_total} ({scripted} scripted) | {} |",
        pool.len()
    );
    println!(
        "| Heroes (hero power scripted) | {heroes_ok} | {} |",
        heroes.len()
    );
    println!("| Tavern spells | {spells_ok} | {} |", spells.len());
    println!("| Trinkets | {trinkets_ok} | {} |", trinkets.len());
    println!("| Dark Gifts | {gifts_ok} | {} |", gifts.len());
    for (title, cards) in [
        ("Timewarp (normal and golden)", &timewarp),
        ("Tier 7", &tier7),
    ] {
        println!(
            "| {title} | {} | {} |",
            cards.iter().filter(|c| implemented(c.cid)).count(),
            cards.len()
        );
    }
    println!();
    println!("Registry presence is coverage, not proof of game-rule accuracy.\n");

    println!("## Shop minions\n");
    println!("| Tier | Card ID | Name | 中文名 | Kind |");
    println!("| --- | --- | --- | --- | --- |");
    let mut rows: Vec<_> = pool.iter().filter(|c| implemented(c.cid)).collect();
    rows.sort_by_key(|c| (c.tier, c.id.clone()));
    for c in rows {
        let kind = if script(c.cid).is_some() {
            "scripted"
        } else {
            "keyword-only"
        };
        println!(
            "| {} | {} | {} | {} | {} |",
            c.tier, c.id, c.name, c.name_zh, kind
        );
    }

    println!("\n## Heroes\n");
    println!("| Hero ID | Hero | 中文名 | Hero power |");
    println!("| --- | --- | --- | --- |");
    let mut hs: Vec<_> = heroes
        .iter()
        .filter(|h| h.hero_power.is_some_and(|hp| script(hp).is_some()))
        .collect();
    hs.sort_by_key(|h| h.id.clone());
    for h in hs {
        let hp = d.get(h.hero_power.unwrap());
        println!(
            "| {} | {} | {} | {} ({}) |",
            h.id, h.name, h.name_zh, hp.name, hp.id
        );
    }

    for (title, list) in [
        ("Tavern spells", &spells),
        ("Trinkets", &trinkets),
        ("Dark Gifts", &gifts),
        ("Timewarp", &timewarp),
        ("Tier 7", &tier7),
    ] {
        println!("\n## {title}\n");
        println!("| Card ID | Name | 中文名 | Tier/size | Cost |");
        println!("| --- | --- | --- | --- | ---: |");
        let mut v: Vec<_> = list.iter().filter(|c| script(c.cid).is_some()).collect();
        v.sort_by_key(|c| c.id.clone());
        for c in v {
            let size = match c.kind {
                CardKind::TrinketLesser => "lesser".to_string(),
                CardKind::TrinketGreater => "greater".to_string(),
                CardKind::DarkGift => format!("turns {:?}", c.window.unwrap()),
                _ => format!("tier {}", c.tier),
            };
            println!(
                "| {} | {} | {} | {} | {} |",
                c.id, c.name, c.name_zh, size, c.cost
            );
        }
    }
    let tokens = [
        "BG20_GEM",
        "TB_BaconShop_Triples_01",
        "BG36_301t",
        "BG36_303",
        "BG36_371",
        "BG36_624",
    ];
    println!("\n## Generated / special cards also scripted\n");
    for t in tokens {
        let c = d.get(d.id(t));
        println!("- {} {} ({})", c.id, c.name, c.name_zh);
    }
}
